const body = $input.first().json.body;

if (!body.clinic_id || !body.lead_id) {
  throw new Error('Payload inválido: clinic_id e lead_id são obrigatórios');
}

const lead = body.lead || {};
const chatHistory = (body.chat_history || [])
  .map(m => `[${m.role === 'clinic' ? 'Clínica' : 'Lead'}]: ${m.content}`)
  .join('\n');

const prompt = `Você é um analista de vendas para clínicas de estética. Analise o lead e o histórico de conversa abaixo e produza um diagnóstico objetivo.

PERFIL DO LEAD:
- Nome: ${lead.name || 'Não informado'}
- Interesse: ${lead.procedure || 'Não informado'}
- Origem: ${lead.source || 'Não informado'}
- Etapa no funil: ${lead.current_stage || 'Não informado'}
- Tags: ${(lead.tags || []).join(', ') || 'Nenhuma'}

HISTÓRICO DA CONVERSA (cronológico):
${chatHistory || 'Sem histórico disponível'}

---
Responda APENAS com um JSON válido (sem markdown, sem texto extra) neste formato exato:
{
  "sentiment": "uma palavra: Interessado | Neutro | Hesitante | Negativo",
  "intent": número de 0 a 100 representando a intenção de compra,
  "consciousness": "nível de consciência do lead, ex: Pronto para Fechar | Consciente da Solução | Consciente do Problema | Explorando",
  "summary": "análise geral em 2-3 frases sobre o perfil e momento do lead",
  "objection": "principal objeção identificada e como interpretá-la, ou null se não houver"
}`;

return [{
  json: {
    clinic_id: body.clinic_id,
    lead_id: body.lead_id,
    prompt
  }
}];

const aiRes = $input.first().json;
const { clinic_id, lead_id } = $('Preparar Prompt').item.json;

// Suporta formato OpenAI nativo do n8n e formato bruto da API
const rawText = aiRes?.message?.content
  || aiRes?.choices?.[0]?.message?.content
  || aiRes?.content?.[0]?.text
  || aiRes?.text
  || '';

if (!rawText) throw new Error('Resposta vazia da IA: ' + JSON.stringify(aiRes));

const text = rawText.replace(/```json\n?/gi, '').replace(/```\n?/gi, '').trim();

let result;
try {
  result = JSON.parse(text);
} catch (_) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Nenhum JSON encontrado na resposta');
  result = JSON.parse(m[0]);
}

// Normalizar
const intent = Math.max(0, Math.min(100, parseInt(result.intent) || 0));
const out = {
  sentiment: result.sentiment || 'Neutro',
  intent,
  consciousness: result.consciousness || 'Explorando',
  summary: result.summary || '',
  objection: result.objection && result.objection !== 'null' ? result.objection : null
};

return [{ json: { clinic_id, lead_id, result: out } }];
